    return navigableList?.element.dataset.cardHotkeysDisabled === "true"
  }

  #keyHandlers = {
    "["(event) { this.#postponeCard(event) },
    "]"(event) { this.#closeCard(event) },
    m(event) { this.#assignToMe(event) }
  }
}
